    uniform_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    uniform_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # For vertical dividers, detect a short motif between repeated separator
    # columns and tile it horizontally through blank slots.
    for div in uniform_cols:
        if div == 0 or div == w - 1:
            continue
        # Preserve separator; mirror/tile foreground of left panel into right.
        for r in range(h):
            for c in range(div):
                v = grid[r][c]
                if v in (1, 6):
                    continue
                dest = 2 * div - c
                if div < dest < w and grid[r][dest] == 1:
                    out[r][dest] = v
