                    dst = sep + 1 + offset
                    if dst >= h or dst in uniform_rows:
                        continue
                    src = offset
                    for c in range(w):
                        if grid[dst][c] == 1:
                            out[dst][c] = grid[src][c]
    # The examples also show pattern motifs repeated horizontally between
    # matching separators; if the test has a populated left pattern and blank
    # right panel, copy the pattern into each corresponding empty panel cell.
    if h >= 3 and w >= 9:
        for r in range(h):
            for c in range(6):
                if grid[r][c] != 1 and grid[r][c] != 6:
                    mirror = 12 - c
