 "content": "def transform(grid):
    """Copy the non-background motif across every full-color divider axis."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Divider axes are uniform rows/columns whose color differs from the field.
    row_axes = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_axes = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    # Collect foreground marks on one side and reflect to empty corresponding cells.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or r in row_axes or c in col_axes:
                continue
            for axis in col_axes:
                cc = 2 * axis - c
                if 0 <= cc < w and grid[r][cc] == bg:
                    out[r][cc] = v
            for axis in row_axes:
                rr = 2 * axis - r
                if 0 <= rr < h and grid[rr][c] == bg:
                    out[rr][c] = v
    return out

